	internal bool CanUseProgressBar()
	{
		if (!base.IsDisposed && toolStripProgressBar_Progress != null && toolStripProgressBar_Progress.Owner != null)
		{
			return !toolStripProgressBar_Progress.Owner.IsDisposed;
		}
		return false;
	}

	internal void SafeSetProgressBar(int maximum, int value)
	{
		if (CanUseProgressBar())
		{
			if (maximum < 1)
			{
				maximum = 1;
			}
			if (toolStripProgressBar_Progress.Maximum != maximum)
			{
				toolStripProgressBar_Progress.Maximum = maximum;
			}
			int num = value;
			if (num < toolStripProgressBar_Progress.Minimum)
			{
				num = toolStripProgressBar_Progress.Minimum;
			}
			if (num > toolStripProgressBar_Progress.Maximum)
			{
				num = toolStripProgressBar_Progress.Maximum;
			}
			toolStripProgressBar_Progress.Value = num;
		}
	}

	internal void SafeSetProgressValue(int value)
	{
		if (CanUseProgressBar())
		{
			int num = value;
			if (num < toolStripProgressBar_Progress.Minimum)
			{
				num = toolStripProgressBar_Progress.Minimum;
			}
			if (num > toolStripProgressBar_Progress.Maximum)
			{
				num = toolStripProgressBar_Progress.Maximum;
			}
			toolStripProgressBar_Progress.Value = num;
		}
	}

