	internal void ShowTaskVersionCompatibilityNotice()
	{
		if (compatibilityNoticeShown || !LoadedTask)
		{
			return;
		}

		int version = GlobalData.version;
		List<string> unsupportedOptions = new List<string>();
		if (version < 175)
		{
			unsupportedOptions.Add("Próxima falha");
			unsupportedOptions.Add("Frequência disponível");
		}
		if (version < 180 || !smethod_11(version, GlobalData.TaskParameters.MultiNpcTalk))
		{
			unsupportedOptions.Add("Diálogo com vários NPCs");
		}
		if (unsupportedOptions.Count == 0)
		{
			return;
		}

		compatibilityNoticeShown = true;
		string message = "tasks.data v" + version + " não suporta: " + string.Join(", ", unsupportedOptions) + ".\nAs opções laranja ficam visíveis, mas bloqueadas.";
		DKBox.Show(this, message, "Compatibilidade da Tasks", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
	}

	private void UpdateOwnerTaskVersion(string taskVersion)
	{
		if (form_0 == null || form_0.IsDisposed)
		{
			return;
		}

		const string marker = " | Tasks v";
		string ownerTitle = form_0.Text ?? string.Empty;
		int markerIndex = ownerTitle.LastIndexOf(marker, StringComparison.OrdinalIgnoreCase);
		if (markerIndex >= 0)
		{
			ownerTitle = ownerTitle.Substring(0, markerIndex);
		}
		form_0.Text = string.IsNullOrWhiteSpace(taskVersion) ? ownerTitle : ownerTitle + marker + taskVersion;
	}

