	protected override void WndProc(ref Message msg)
	{
		try
		{
			if (msg.Msg.Equals(Messages.M_SELECTTASK))
			{
				GlobalData.TASKELEMENTS_TYPE taskelements_TYPE_ = (GlobalData.TASKELEMENTS_TYPE)(int)msg.LParam;
				if ((uint)(int)msg.WParam == GProD.Tasks[0].m_ID)
				{
					treeView_tasks.SelectedNode = treeView_tasks.Nodes[0];
					TaskElements.SelectElement(this, 0, 0, 0, taskelements_TYPE_, ataskTempl_0);
					return;
				}
				int[] array = Search.next_treeNode(treeView_tasks.Nodes[0]);
				while (true)
				{
					if (array.Length != 0)
					{
						if (Search.search(this, array, Search.SearchType.enumSTID, 0, ((uint)(int)msg.WParam).ToString()))
						{
							break;
						}
						array = Search.next_task(array);
						continue;
					}
					return;
				}
				TaskElements.SelectElement(this, 0, 0, 0, taskelements_TYPE_, ataskTempl_0);
			}
			else
			{
				base.WndProc(ref msg);
			}
		}
		catch
		{
		}
	}

