	private void numericUpDown_Award_m_ulCandItems_ValueChanged(object sender, EventArgs e)
	{
		if (award_DATA_0 == null || Selecting || SelectingAward)
		{
			return;
		}
		try
		{
			if (award_DATA_0.m_ulCandItems == Convert.ToInt32(numericUpDown_Award_m_ulCandItems.Value))
			{
				return;
			}
			award_DATA_0.m_ulCandItems = Convert.ToInt32(numericUpDown_Award_m_ulCandItems.Value);
			toolStripComboBox_0.SelectedIndex = -1;
			toolStripComboBox_1.SelectedIndex = -1;
			if (award_DATA_0.m_CandItems.Length < award_DATA_0.m_ulCandItems)
			{
				award_DATA_0.m_CandItems = award_DATA_0.m_CandItems.Resize(award_DATA_0.m_ulCandItems);
				for (int i = checkedListBox_Award_m_CandItems_m_bRandChoose.Items.Count; i < award_DATA_0.m_ulCandItems; i++)
				{
					award_DATA_0.m_CandItems[i] = new AWARD_ITEMS_CAND();
					award_DATA_0.m_CandItems[i].m_AwardItems = new ITEM_WANTED[0];
					checkedListBox_Award_m_CandItems_m_bRandChoose.Items.Add(Class16.smethod_0(1648924364) + (i + 1) + Class16.smethod_0(1649008474) + GProD.TX(406), isChecked: false);
					toolStripComboBox_0.Items.Add(Class16.smethod_0(1648924364) + (i + 1) + Class16.smethod_0(1649008474) + GProD.TX(406));
					toolStripComboBox_1.Items.Add(Class16.smethod_0(1648924364) + (i + 1) + Class16.smethod_0(1649008474) + GProD.TX(406));
					if (award_DATA_0 != null && award_DATA_0.m_ulCandItems == 1)
					{
						checkedListBox_Award_m_CandItems_m_bRandChoose.SelectedIndex = 0;
					}
				}
				if (ACE.sTASKedit.Classes.Settings.Fields.EnableShowTips)
				{
					DKBox.Show(GProD.TX(407), string.Empty);
				}
			}
			if (award_DATA_0.m_CandItems.Length > award_DATA_0.m_ulCandItems)
			{
				AWARD_ITEMS_CAND[] array = new AWARD_ITEMS_CAND[award_DATA_0.m_ulCandItems];
				Array.Copy(award_DATA_0.m_CandItems, array, array.Length);
				award_DATA_0.m_CandItems = array;
				for (int j = 0; j < dataGridView_Award_m_CandItems_m_AwardItems.RowCount; j++)
				{
					if (Convert.ToInt32(dataGridView_Award_m_CandItems_m_AwardItems.Rows[j].Cells[0].Value) >= award_DATA_0.m_ulCandItems)
					{
						dataGridView_Award_m_CandItems_m_AwardItems.Rows.RemoveAt(j);
						j--;
