			num2 = ataskTempl_0.m_usMutexTasksSpace[e.RowIndex];
		}
		else if (dataGridView == dataGridView_2)
		{
			num = 8;
			num2 = ataskTempl_0.m_TeamMemsWanted[e.RowIndex].TeamMemTaskSpace;
		}
		else if (dataGridView == dataGridView_10)
		{
			num = 1;
			num2 = ataskTempl_0.m_usNeededTasksSpace[e.RowIndex];
		}
		else if (dataGridView == dataGridView_TaskEventTaskData)
		{
			num = 1;
			num2 = ataskTempl_0.TaskEventTaskData[e.RowIndex].IdSpace;
		}
		else if (dataGridView == dataGridView_SpecialParameters_CompleteTaskIDs)
		{
			num = 1;
			num2 = ataskTempl_0.SpecialParameters.CompleteTaskIDsSpace[e.RowIndex];
		}
		if (num > -1 && e.ColumnIndex == num)
		{
			toolTip_Special.Hide((Control)sender);
			dataGridView.ShowCellToolTips = true;
			object value = dataGridView.Rows[e.RowIndex].Cells[e.ColumnIndex].Value;
			if (value != null)
			{
				GoToTask(num2.ToString(), value.ToString());
			}
		}
	}

	public void GoToTask(string TaskIdSpace, string TaskId)
	{
		if (!(TaskId != Class16.smethod_0(1648924112)) || !(TaskId != string.Empty))
		{
			return;
		}
		if (TaskIdSpace == GProD.Tasks[0].m_usIDSpace.ToString() && TaskId == GProD.Tasks[0].m_ID.ToString())
		{
			treeView_tasks.SelectedNode = treeView_tasks.Nodes[0];
			return;
		}
		int[] array = Search.next_treeNode(treeView_tasks.Nodes[0]);
		while (array.Length != 0 && !Search.search(this, array, Search.SearchType.enumSTID, Convert.ToInt32(TaskIdSpace), TaskId))
		{
			array = Search.next_task(array);
		}
	}

