		else
		{
			switch (ulPremise_Period)
			{
			case 30:
				comboBox_m_ulPremise_Period.SelectedIndex = 10;
				break;
			case 31:
				comboBox_m_ulPremise_Period.SelectedIndex = 12;
				break;
			case 32:
				comboBox_m_ulPremise_Period.SelectedIndex = 14;
				break;
			case 20:
