				break;
			case 22:
				comboBox_m_ulPremise_Period.SelectedIndex = 13;
				break;
			case 41:
				comboBox_m_ulPremise_Period.SelectedIndex = 16;
				break;
			case 40:
				comboBox_m_ulPremise_Period.SelectedIndex = 15;
				break;
			}
		}
